import{H as e,V as t,et as n,j as r}from"./chunks/framework.BY5yoHkb.js";var i=JSON.parse(`{"title":"「图种」技术：一张图片如何藏下整个压缩包？","description":"","frontmatter":{"title":"「图种」技术：一张图片如何藏下整个压缩包？","date":"2026-06-20T00:00:00.000Z","tags":["图种","技巧","文件隐藏","科普"]},"headers":[],"relativePath":"posts/lore/「图种」技术：一张图片如何藏下整个压缩包？.md","filePath":"posts/lore/「图种」技术：一张图片如何藏下整个压缩包？.md"}`),a={name:`posts/lore/「图种」技术：一张图片如何藏下整个压缩包？.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<p>“图种”是一种将图片文件与压缩文件巧妙结合的技术。生成的文件外观与普通图片无异，可以正常预览，但实际上在图片数据之后还隐藏着完整的压缩包数据。</p><h2 id="工作原理-为什么一张图能-一图两用" tabindex="-1">工作原理：为什么一张图能“一图两用”？ <a class="header-anchor" href="#工作原理-为什么一张图能-一图两用" aria-label="Permalink to “工作原理：为什么一张图能“一图两用”？”">​</a></h2><p>这主要利用了不同文件格式对“文件头”和“文件尾”的识别机制。</p><p>以最常见的 JPG 图片和 RAR 压缩包为例：</p><ul><li><strong>对图片查看器而言</strong>：JPG 格式有固定的结束标志。图片查看器读到这个标志后就会停止读取，忽略后面附加的任何数据，只显示图片内容。</li><li><strong>对解压软件而言</strong>：RAR 格式有固定的开始标志。解压软件会直接定位到这个标志，并读取其后完整的压缩包数据，而忽略前面无关的图片信息。</li></ul><p>因此，同一个文件可以同时被图片查看器和压缩软件正确识别，互不干扰。</p><h2 id="常见制作方法-如何制作一个图种" tabindex="-1">常见制作方法：如何制作一个图种？ <a class="header-anchor" href="#常见制作方法-如何制作一个图种" aria-label="Permalink to “常见制作方法：如何制作一个图种？”">​</a></h2><p>最经典的方法是利用 Windows 系统自带的 <code>copy</code> 命令，以二进制方式合并文件。</p><ol><li><strong>准备材料</strong>：一张普通图片（如 <code>photo.jpg</code>）和一个需要隐藏的压缩包（如 <code>data.rar</code>）。</li><li><strong>执行合并</strong>：打开命令行，进入文件所在目录，输入以下命令： copy /b photo.jpg + data.rar output.jpg 06-20 08:47:26 这个命令会将 <code>data.rar</code> 的二进制数据“附加”到 <code>photo.jpg</code> 的后面，生成新文件 <code>output.jpg</code>。</li><li><strong>完成</strong>：生成的 <code>output.jpg</code> 就是图种文件。直接双击它，会像普通图片一样正常打开。</li></ol><h2 id="如何提取图种中的隐藏文件" tabindex="-1">如何提取图种中的隐藏文件？ <a class="header-anchor" href="#如何提取图种中的隐藏文件" aria-label="Permalink to “如何提取图种中的隐藏文件？”">​</a></h2><p>提取同样非常简单，无需专门工具：</p><ul><li><strong>方法一（改后缀）</strong>：将图种文件的扩展名从 <code>.jpg</code> 直接改为 <code>.rar</code>，然后用解压软件打开。</li><li><strong>方法二（直接打开）</strong>：在 WinRAR 等软件中，通过“文件 → 打开”直接选择该 <code>.jpg</code> 文件，软件会自动识别并显示压缩包内容。</li></ul><h2 id="用途与特点" tabindex="-1">用途与特点 <a class="header-anchor" href="#用途与特点" aria-label="Permalink to “用途与特点”">​</a></h2><p>图种技术主要有以下特点：</p><ul><li><strong>隐蔽性强</strong>：文件以常见图片格式存在，不易引起注意。</li><li><strong>操作简单</strong>：制作和提取都不需要复杂的专业工具，系统自带功能或常见压缩软件即可完成。</li><li><strong>灵活通用</strong>：不仅可以合并压缩包，理论上任何文件都可以用类似方式附加到图片之后。</li></ul><p>总而言之，图种是一种通过巧妙利用文件格式特征来实现信息隐藏的实用技术。无论是用来传递加密信息，还是单纯作为一种有趣的数字把戏，它都展示了计算机世界里“所见未必所得”的奇妙一面。</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};